assert_equals "enrollments exposes the required columns and nullability" "SELECT GROUP_CONCAT(CONCAT(COLUMN_NAME,':',COLUMN_TYPE,':',IS_NULLABLE) ORDER BY COLUMN_NAME SEPARATOR ';') FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='enrollments'" "course_id:int:NO;enrolled_on:date:NO;grade:decimal(4,2):YES;participant_id:int:NO"
# Test descriptions are in English. SQL assertions use the isolated test database.
assert_equals "enrollments has the required primary key" "SELECT GROUP_CONCAT(COLUMN_NAME ORDER BY ORDINAL_POSITION) FROM information_schema.KEY_COLUMN_USAGE WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='enrollments' AND CONSTRAINT_NAME='PRIMARY'" "participant_id,course_id"
assert_accepts "Both sides can have several associations" "INSERT INTO enrollments VALUES(1,1,'2026-10-01',NULL),(1,2,'2026-10-02',8.50),(2,1,'2026-10-01',10.00)"
assert_rejects "Duplicate enrollment is rejected" "1062" "INSERT INTO enrollments VALUES(1,1,'2026-10-03',NULL)"
assert_rejects "Unknown participants are rejected" "1452" "INSERT INTO enrollments VALUES(99,1,'2026-10-01',NULL)"
assert_rejects "Unknown courses are rejected" "1452" "INSERT INTO enrollments VALUES(1,99,'2026-10-01',NULL)"
assert_rejects "Grades above ten are rejected" "3819" "UPDATE enrollments SET grade=11 WHERE participant_id=1 AND course_id=1"
assert_rejects "Negative grades are rejected" "3819" "UPDATE enrollments SET grade=-1 WHERE participant_id=1 AND course_id=1"
assert_rejects "An enrolled participant cannot be deleted" "1451" "DELETE FROM participants WHERE id=1"
assert_rejects "An attended course cannot be deleted" "1451" "DELETE FROM courses WHERE id=1"
